#include <iostream>
using namespace std;

int H, W, K;
string S[200001];
int X[200001], D[200001];

int main(void){
  cin >> H >> W >> K;
  for(int i = 1; i <= H; i++) cin >> S[i];
  for(int i = 1; i <= H; i++) S[i] = "#" + S[i]; //添字を解説本文と揃えるためだけの便宜上の処理です

  int ans = 1e9;
  for(int y = 1; y <= H; y++){
    for(int i = 1; i <= W; i++){
      X[i] = X[i-1], D[i] = D[i-1];
      if(S[y][i] == 'x') X[i]++;
      if(S[y][i] == '.') D[i]++;
    }
    for(int i = 1; i <= W-K+1; i++){
      if(X[i+K-1]-X[i-1] == 0) ans = min(ans, D[i+K-1]-D[i-1]);
    }
  }
  for(int x = 1; x <= W; x++){
    for(int i = 1; i <= H; i++){
      X[i] = X[i-1], D[i] = D[i-1];
      if(S[i][x] == 'x') X[i]++;
      if(S[i][x] == '.') D[i]++;
    }
    for(int i = 1; i <= H-K+1; i++){
      if(X[i+K-1]-X[i-1] == 0) ans = min(ans, D[i+K-1]-D[i-1]);
    }
  }

  if(ans > K) ans = -1;
  cout << ans << endl;
  return 0;
}
